<?php
require_once __DIR__ . '/_init.php'; mc_admin_require_login(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){mc_csrf_check();$action=$_POST['action']??'upload';if($action==='delete'){$rel=mc_safe_local_path($_POST['path']??'');if(strpos($rel,'uploads/media/')===0){$abs=MC_ROOT.'/'.$rel;if(is_file($abs))@unlink($abs);}mc_flash('success','Imagen eliminada de la biblioteca.');header('Location: media.php');exit;}else{$up=mc_upload_image('image','media');if(!$up['ok'])$error=$up['error'];elseif($up['path']==='')$error='Selecciona una imagen.';else{mc_flash('success','Imagen subida correctamente. Ruta: '.$up['path']);header('Location: media.php');exit;}}}
$dir=MC_ROOT.'/uploads/media';$files=[];if(is_dir($dir)){foreach(glob($dir.'/*')?:[] as $f){if(is_file($f))$files[]='uploads/media/'.basename($f);}rsort($files);}mc_admin_header('Biblioteca de imágenes');?><?php if($error):?><div class="alert error"><?=mc_h($error)?></div><?php endif;?><section class="card" style="margin-bottom:18px"><h2>Subir imagen</h2><form method="post" enctype="multipart/form-data" class="actions"><input type="hidden" name="csrf" value="<?=mc_h(mc_csrf_token())?>"><input type="hidden" name="action" value="upload"><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif" required><button class="btn primary">Subir imagen</button></form><p class="help">La ruta resultante puede usarse en contenidos o conservarse como biblioteca. Máximo 6 MB.</p></section><section class="card"><h2>Imágenes disponibles</h2><?php if(!$files):?><p class="help">Todavía no hay imágenes en la biblioteca.</p><?php else:?><div class="media-grid"><?php foreach($files as $rel):?><div class="media-item"><img src="../<?=mc_h($rel)?>" alt=""><div class="meta"><code title="<?=mc_h($rel)?>"><?=mc_h($rel)?></code><div class="actions" style="margin-top:8px"><button type="button" class="btn light" onclick="navigator.clipboard&&navigator.clipboard.writeText('<?=mc_h($rel)?>');this.textContent='Copiado'">Copiar ruta</button><form method="post" onsubmit="return confirm('¿Eliminar imagen?')"><input type="hidden" name="csrf" value="<?=mc_h(mc_csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="path" value="<?=mc_h($rel)?>"><button class="btn danger">Eliminar</button></form></div></div></div><?php endforeach;?></div><?php endif;?></section><?php mc_admin_footer();?>